import {join,dirname,resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage} from '../scripts/run-istanbul-bun-coverage';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-remote-diagnostic-');
const paths=["src/infrastructure/database/leased-operation-admission.ts","src/infrastructure/database/leased-operation-admission.test.ts","src/infrastructure/database/source-operation-admission.ts","src/infrastructure/database/source-operation-admission.test.ts","src/infrastructure/database/sqlite-operation-admission.ts","src/infrastructure/database/sqlite-operation-admission.test.ts"];

const tests=paths.filter(path=>path.endsWith('.test.ts'));
const mode=process.argv[2]??'measure';if(!['measure','faults'].includes(mode))throw Error('Invalid mode');
const originals=new Map(paths.map(path=>[path,readFileSync(path,'utf8')]));
const typePath='src/presentation/cli/commands/sync/types.ts',typeHash=sourceHash(readFileSync(typePath,'utf8'));
function put(path:string,content:string){mkdirSync(dirname(join(storage.dir,path)),{recursive:true});writeFileSync(join(storage.dir,path),content.replace(/from "commander"/g,'from '+JSON.stringify(Bun.resolveSync('commander',root))));}
const runs:any[]=[];

const faults=[{"path":"src/infrastructure/database/leased-operation-admission.ts","kind":"ignore-authority","from":"!owner || owner.authority !== this.authority","to":"!owner","pattern":"wrong-source"},{"path":"src/infrastructure/database/leased-operation-admission.ts","kind":"accept-expired","from":"if (!ancestor.open)","to":"if (false)","pattern":"explicit children|detached child work"},{"path":"src/infrastructure/database/leased-operation-admission.ts","kind":"ignore-active-child","from":"if (owner.child)","to":"if (false)","pattern":"explicit children"},{"path":"src/infrastructure/database/leased-operation-admission.ts","kind":"release-before-child","from":"await frame.child.done;","to":"","pattern":"detached child work"},{"path":"src/infrastructure/database/leased-operation-admission.ts","kind":"hide-unawaited-child","from":"frame.failures.push(new Error(\"Operation callback completed with unawaited child work\"));","to":"","pattern":"detached child work"},{"path":"src/infrastructure/database/leased-operation-admission.ts","kind":"lose-child-failure","from":"if (frame.parent) frame.parent.failures.push(error);","to":"","pattern":"caught child failure|outer and detached"},{"path":"src/infrastructure/database/leased-operation-admission.ts","kind":"forget-compound-error","from":"throw new AggregateError(failures, \"Operation scope and child work failed\")","to":"throw failures[0]","pattern":"outer and detached"},{"path":"src/infrastructure/database/leased-operation-admission.ts","kind":"forget-scope-close","from":"frame.open = false;","to":"","pattern":"explicit children|detached child work"},{"path":"src/infrastructure/database/leased-operation-admission.ts","kind":"omit-nested-post-validation","from":"try { this.validate(); } catch (error) { frame.failures.push(error); }","to":"","pattern":"post-operation alias"},{"path":"src/infrastructure/database/source-operation-admission.ts","kind":"ignore-source-issuer","from":"parent !== undefined && !issuedSourceLeases.has(parent)","to":"false","pattern":"different wrapper"}];

try {
 for(const [path,content]of originals){
  for(const match of content.matchAll(/(?:from\s+|import\s*\()\s*["'](\.[^"']+)["']/g)) {
   const target=resolve(dirname(path),match[1]).replace(/\.js$/,'.ts'),local=target.slice(root.length+1).replaceAll('\\','/');
   if(!paths.includes(local))put(local,'export * from '+JSON.stringify(target.replaceAll('\\','/'))+';');
  }
  for(const match of content.matchAll(/source\("([^"]+)"\)/g)){
   const local='src/'+match[1];if(!paths.includes(local))put(local,'export * from '+JSON.stringify(resolve(local).replaceAll('\\','/'))+';');
  }
 }
 put('capture.ts','import {afterAll} from "bun:test";import {writeFileSync} from "node:fs";afterAll(()=>writeFileSync("coverage.json",JSON.stringify((globalThis as any).__coverage__)));');
 put('bunfig.toml','[test]\ncoverage=false\npreload=['+JSON.stringify(join(root,'tests/test-setup.ts').replaceAll('\\','/'))+(mode==='measure'?',"./capture.ts"':'')+']\n');
 for(const fault of [null,...(mode==='faults'?faults:[])]) {
  for(const [path,content]of originals)put(path,mode==='measure'?instrumentTypeScriptWithCoverage(content,resolve(path)).code:content);
  if(fault){let content=originals.get(fault.path)!;const index=content.indexOf(fault.from);if(index<0)throw Error('Missing fault '+fault.kind);put(fault.path,content.slice(0,index)+fault.to+content.slice(index+fault.from.length));}
  const command=[process.execPath,'test','--timeout','15000',...tests,...(fault?['--test-name-pattern',fault.pattern]:[])];
  const child=Bun.spawnSync(command,{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:90000});
  const output=new TextDecoder().decode(child.stdout)+new TextDecoder().decode(child.stderr);runs.push({fault,command,exit:child.exitCode,output});
  writeFileSync('.git/q100-lease-diagnostic-progress.json',JSON.stringify({runs},null,2));
  if(!fault&&child.exitCode!==0)throw Error('Control failed\n'+output);
  if(fault&&child.exitCode!==0&&!output.includes('(fail)'))throw Error('Fault did not reach assertions\n'+output);
 }
 let measurement;
 if(mode==='measure'){
  const raw=JSON.parse(readFileSync(join(storage.dir,'coverage.json'),'utf8')),map=createCoverageMap(raw);
  measurement={rawCoverage:raw,files:paths.map(path=>{const measured=map.fileCoverageFor(resolve(path)),data=measured.data;return {path,sourceHash:sourceHash(originals.get(path)!),metrics:measured.toSummary().data,uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.flatMap((count,index)=>count===0?[{id,index,location:data.branchMap[id]?.locations[index]}]:[])),uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id])};})};
  console.log(JSON.stringify(measurement.files.map(file=>({path:file.path,metrics:file.metrics}))));
 }else console.log(JSON.stringify(runs.map(run=>({fault:run.fault?.kind,exit:run.exit}))));
 writeFileSync(`.git/q100-lease-${mode}.json`,JSON.stringify({recordedAt:new Date().toISOString(),runtime:Bun.version,scope:'Scoped diagnostic only; child process instrumentation is not aggregated. No full quality acceptance.',sourceInputs:[...paths.map(path=>({path,sourceHash:sourceHash(originals.get(path)!)})),{path:typePath,sourceHash:typeHash}],runs,measurement,source:readFileSync('.git/q100-lease-diagnostic.ts','utf8')},null,2)+'\n');
} finally { storage.cleanup(); }

